 static JObject Call(SupervisorManagerConnection connection,string op,JObject payload)=>connection.Call(op,payload).GetAwaiter().GetResult();
 static void DescriptorPublication(string path){
  string fresh=path+".sharing-check";File.Copy(path,fresh);
  using(var blocked=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){bool refused=false;try{File.Replace(fresh,path,null);}catch(IOException e){refused=e.HResult==unchecked((int)0x80070020);}Need(refused,"descriptor-sharing-negative");}
