 public static int Main(string[] args){try{string root=args[0];Directory.CreateDirectory(root);var clock=System.Diagnostics.Stopwatch.StartNew();var journal=new JournalActor(Path.Combine(root,"journal"),16);journal.Initialized.GetAwaiter().GetResult();var launcher=new Launcher(clock);var runtime=new SupervisorRuntime(journal,launcher,new WatchdogPolicy(1000,200,50,RuntimeLimits.ProcessBytes,1000,1000),4,4L*RuntimeLimits.ProcessBytes,()=>clock.ElapsedMilliseconds);var storage=new StorageBroker(Path.Combine(root,"storage"),4);storage.Initialized.GetAwaiter().GetResult();
