   Need((bool?)Remove(connection,Guid.Empty)["ok"]==false,"empty-accepted");Need((bool?)Call(connection,"UninstallInstallation",new JObject{{"host",Guid.NewGuid().ToString("N")},{"installation",target.ToString("N")}})["ok"]==false,"foreign-host-accepted");
   var reserved=Start(connection,target,Guid.NewGuid(),true);Need((bool?)reserved["ok"]==true,"reserve");Need((bool?)Remove(connection,target)["ok"]==false,"reserved-installation-deleted");var token=new JObject{{"host",connection.Host.ToString("N")},{"token",(string)reserved["token"]}};Call(connection,"StopSession",token);
   launcher.Gate.Reset();Guid instance=Guid.NewGuid();Need((bool?)Start(connection,target,instance)["ok"]==true,"start");Need((bool?)Remove(connection,target)["ok"]==false,"pending-start-deleted");launcher.Gate.Set();Wait(()=> (string)Call(connection,"Status",new JObject())["instances"]?[instance.ToString("N")]?["state"]=="Running");Need((bool?)Remove(connection,target)["ok"]==false,"running-installation-deleted");Call(connection,"Stop",new JObject{{"instance",instance.ToString("N")}});Wait(()=>Call(connection,"Status",new JObject())["instances"]?[instance.ToString("N")]==null);Need((bool?)Remove(connection,target)["ok"]==true,"stopped-installation-refused");
