    try{var pending=Task.Run(()=>Remove(connection,target));Need(pending.Wait(1800)&&(bool?)pending.Result["ok"]==false,"uninstall-deadline");Need((bool?)Start(connection,target,Guid.NewGuid())["ok"]==false&&(bool?)Start(connection,target,Guid.NewGuid(),true)["ok"]==false,"timed-out-removal-lost-start-guard");}finally{release.Set();PrivateStore.BeforeReplace=null;}
    Need(write.Result.Failure==StorageFailure.None,"neighbor-write-failed");Wait(()=> (bool?)Remove(connection,target)["ok"]==true);
   }
   var descriptorValue=JObject.Parse(File.ReadAllText(descriptor));descriptorValue["auth"]=Convert.ToBase64String(new byte[32]);string bad=Path.Combine(root,"bad.json");File.WriteAllText(bad,descriptorValue.ToString());Need((bool?)Remove(new SupervisorManagerConnection(bad),target)["ok"]==false,"unauthenticated-remove");
   var uninstallMethod=typeof(SupervisorManagerConnection).GetMethod("UninstallInstallation");Need(uninstallMethod!=null,"missing-manager-uninstall-api");((Task)uninstallMethod.Invoke(connection,new object[]{target})).GetAwaiter().GetResult();Need(storage.Read(neighborSession,"save").Result.Value[0]==3,"neighbor-final-data");neighborSession.Close();
  }}finally{launcher.Gate.Set();runtime.Close();runtime.Completion.GetAwaiter().GetResult();storage.Close();storage.Completion.GetAwaiter().GetResult();journal.Close();journal.Completion.GetAwaiter().GetResult();}
  Console.WriteLine("PASS authenticated uninstall, reserved/pending/running ownership, timeout start guard, neighbor preservation and authentication");return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
